ickup Error\') ,(\'UNDELIVERED-1ST ATTEMPT\',\'In Transit\') ,(\'Not Traceble\',\'Pickup Error\') ,(\'UNDELIVERED\',\'In Transit\') ,(\'LOST\',\'Lost\') ,(\'IN TRANSIT-EN-ROUTE\',\'In Transit\') ,(\'Indian Speed Post\',\'Indian Speed Post\') ,(\'Exception\',\'Exception\') ,(\'Shipment Booked\',\'Pickup Error\') ,(\'Assigned\',\'Assigned\') ,(\'Pending\',\'Pending\') ,(\'Printed\',\'Printed\') ,(\'IN TRANSIT-AT DESTINATION HUB\',\'In Transit\') ,(\'Upcoming\',\'Order Yet To sync\') ,(\'RTO-In Transit\',\'RTO\') ,(\'PICKUP ERROR\',\'Pickup Error\') ,(\'RTO-Out for Delivery\',\'RTO\') ,(\'RTO-Delivered\',\'RTO\') ,(\'OUT FOR PICKUP\',\'Pickup Error\') ,(\'RTO_NDR\',\'RTO\') ,(\'RTO-Exception\',\'Exception\') ,(\'Delayed\',\'In Transit\') ,(\'IN TRANSIT-AT SOURCE HUB\',\'In Transit\') ,(\'RTS\',\'Underprocess\') ,(\'Manifested\',\'Pickup Error\') ,(\'Dispatched\',\'In Transit\') ,(\'RTO\',\'RTO\') ,(\'Not Picked\',\'Pickup Error\') ,(\'DAMAGED\',\'Damaged\') ,(\'Closed\',\'Cancelled\') ,(\'Open\',\'Open\') ,(\'On Hold\',\'On Hold\') ,(\'Shipped - Returned to Seller\',\'RTO\') ,(\'Shipped - Delivered to Buyer\',\'Delivered\') ,(\'Shipped - Picked Up\',\'In Transit\') ,(\'Shipped - Rejected by Buyer\',\'RTO\') ,(\'Shopify_Processed\',\'Shopify_Processed\') ,(\'Ready to dispatch\',\'Ready to Dispatch\') ,(\'RTO Undelivered\',\'RTO\') ,(\'Shipment Lost\',\'Lost\') ,(\'Shipment Error\',\'Shipment Error\') ,(\'RTO In-Transit\',\'RTO\') ,(\'Dispatch / RTO\',\'RTO\') ,(\'Pending Pick-up\',\'Pending\') ,(\'Dispatch/Intransit\',\'In Transit\') ,(\'Dispatch /Lost and Damange\',\'Lost\') ,(\'Dispatch /Undelivered\',\'Undelivered\') ,(\'Non serviceable\',\'Non Serviceable\') ,(\'Not serviceable\',\'Non Serviceable\') ,(\'Dispatch/Delivered\',\'Delivered\') ,(\'Refund\',\'Refund\') ,(\'F&P\',\'F&P\') ,(\'SHIPPED - RETURNING TO SELLER\',\'RTO\') ,(\'SHIPPED - LOST IN TRANSIT\',\'Lost\') ,(\'SHIPPED - DAMAGED\',\'Damaged\') ,(\'SHIPPED - OUT FOR DELIVERY\',\'Out for delivery\'); create or replace table RUBYSORGANICS_DB.MAPLEMONK.RUBYSORGANICS_DB_sales_consolidated_intermediate as select b.customer_id ,upper(b.SHOP_NAME) SHOP_NAME ,upper(b.shop_name) as marketplace ,Upper(b.FINAL_UTM_CHANNEL) AS CHANNEL ,Upper(b.FINAL_UTM_SOURCE) AS SOURCE ,b.ORDER_ID ,order_name reference_code ,b.PHONE ,b.NAME ,b.EMAIL ,coalesce(b.shipping_status_update_date,c.shipping_last_update_date::datetime, d.shipping_last_update_date::datetime) AS SHIPPING_LAST_UPDATE_DATE ,b.SKU ,b.PRODUCT_ID ,Upper(b.PRODUCT_NAME) PRODUCT_NAME ,b.CURRENCY ,Upper(b.CITY) As CITY ,Upper(b.STATE) AS State ,Upper(b.ORDER_STATUS) ORDER_STATUS ,b.ORDER_TIMESTAMP::date AS Order_Date ,b.ORDER_TIMESTAMP ,b.QUANTITY ,b.GROSS_SALES_BEFORE_TAX AS GROSS_SALES_BEFORE_TAX ,b.DISCOUNT AS DISCOUNT ,b.TAX ,b.SHIPPING_PRICE ,b.TOTAL_SALES AS SELLING_PRICE ,UPPER(coalesce(c.order_status,d.order_status)) as OMS_order_status ,UPPER(coalesce(b.shipping_status, c.shipping_status,d.shipping_status)) AS SHIPPING_STATUS ,upper(coalesce(shipmap.final_shipping_status,b.shipping_status, c.shipping_status,d.shipping_status)) FINAL_SHIPPING_STATUS ,b.LINE_ITEM_ID::varchar as SALEORDERITEMCODE ,d.sales_order_item_id as SALES_ORDER_ITEM_ID ,coalesce(b.awb,c.awb,d.awb) AWB ,upper(replace(parse_json(GATEWAY)[0],\'\"\',\'\')) PAYMENT_GATEWAY ,upper(coalesce(c.payment_mode,d.payment_mode)) Payment_Mode ,Upper(coalesce(c.Courier,d.courier,b.courier)) AS COURIER ,coalesce(b.Shipping_created_at,c.manifest_date,d.dispatch_date) AS DISPATCH_DATE ,coalesce(c.delivered_date,d.delivery_date,case when b.shipping_status like \'delivered\' then b.shipping_status_update_date end) AS DELIVERED_DATE ,case when lower(coalesce(shipmap.final_shipping_status,b.shipping_status, c.shipping_status,d.shipping_status)) = \'delivered\' then 1 else 0 end AS DELIVERED_STATUS ,coalesce(case when b.IS_REFUND=1 and lower(b.order_status) not in (\'cancelled\') then 1 end,c.IS_REFUND, d.return_flag) AS RETURN_FLAG ,case when RETURN_FLAG = 1 and lower(b.order_status) not in (\'cancelled\') then ifnull(refund_quantity,0) end returned_quantity ,case when RETURN_FLAG = 1 and lower(b.order_status) not in (\'cancelled\') then ifnull(refund_value,0) end returned_sales ,case when lower(b.order_status) in (\'cancelled\') then quantity::int end cancelled_quantity ,b.shopify_new_customer_flag as NEW_CUSTOMER_FLAG ,Upper(b.shopify_acquisition_product) as acquisition_product ,case when lower(coalesce(shipmap.final_shipping_status,b.shipping_status, c.shipping_status,d.shipping_status)) in (\'delivered\',\'delivered to origin\') then datediff(day,date(b.ORDER_TIMESTAMP),date(coalesce(b.shipping_status_update_date,c.shipping_last_update_date::datetime, d.shipping_last_update_date::datetime))) when lower(coalesce(shipmap.final_shipping_status,b.shipping_status, c.shipping_status,d.shipping_status)) in (\'in transit\', \'shipment created\') then datediff(day,date(b.ORDER_TIMESTAMP), getdate()) end::int as Days_in_Shipment ,b.shopify_acquisition_date AS ACQUSITION_DATE ,b.SKU_CODE ,UPPER(b.PRODUCT_NAME_FINAL) PRODUCT_NAME_FINAL ,UPPER(b.PRODUCT_CATEGORY) PRODUCT_CATEGORY ,upper(b.PRODUCT_SUB_CATEGORY) PRODUCT_SUB_CATEGORY ,upper(c.warehouse_name) WAREHOUSE ,coalesce(b.pincode,c.pincode) as pincode ,coalesce(c.source_pincode,null) as source_pincode from RUBYSORGANICS_DB.MAPLEMONK.RUBYSORGANICS_DB_SHOPIFY_FACT_ITEMS b left join (select * from ( select * ,row_number()over(partition by reference_code,Marketplace_LineItem_ID order by last_update_date desc) rw from RUBYSORGANICS_DB.MAPLEMONK.RUBYSORGANICS_DB_EasyEcom_FACT_ITEMS ) z where z.rw = 1 and lower(marketplace) like any (\'%shopify%\') ) c on replace(b.order_name,\'#\',\'\') = c.reference_code and b.LINE_ITEM_ID=c.Marketplace_LineItem_ID left join (select * from (select order_id ,city ,state ,saleorderitemcode ,sales_order_item_id ,shippingpackagecode ,SHIPPINGPACKAGESTATUS ,shipping_status ,order_status ,Courier ,Dispatch_Date ,Delivery_date ,Return_flag ,Return_quantity ,cancelled_quantity ,shipping_last_update_date ,awb ,payment_method ,PAYMENT_MODE ,email ,row_number() over (partition by order_id, split_part(saleorderitemcode,\'-\',0) order by shipping_last_update_date desc) rw from RUBYSORGANICS_DB.MAPLEMONK.RUBYSORGANICS_DB_UNICOMMERCE_FACT_ITEMS where lower(marketplace) like any (\'%shopify%\')) where rw=1 ) d on b.order_id=d.order_id and b.line_item_id=split_part(d.saleorderitemcode,\'-\',0) left join ( select * from ( select upper(Shipping_status) shipping_status ,upper(mapped_status) final_shipping_status ,row_number() over (partition by lower(shipping_Status) order by 1) rw from RUBYSORGANICS_DB.MAPLEMONK.shipment_status_mapping ) where rw = 1 ) ShipMap on lower(coalesce(b.shipping_status,c.shipping_status,d.shipping_status,b.ORDER_STATUS)) = lower(ShipMap.shipping_status) union all select Null as customer_id ,upper(afi.SHOP_NAME) Shop_name ,\'AMAZON\' as marketplace ,\'AMAZON\' AS CHANNEL ,\'AMAZON\' AS SOURCE ,afi.ORDER_ID ,afi.ORDER_ID reference_code ,Null as PHONE ,NAME ,coalesce(EEFI.EMAIL,UFI.EMAIL,AFI.EMAIL) AS EMAIL ,coalesce(EEFI.shipping_last_update_date::datetime, UFI.shipping_last_update_date::datetime) AS SHIPPING_LAST_UPDATE_DATE ,afi.SKU ,afi.PRODUCT_ID ,afi.PRODUCT_NAME ,afi.CURRENCY ,Upper(afi.CITY) CITY ,UPPER(afi.STATE) AS State ,UPPER(afi.ORDER_STATUS) Order_Status ,afi.ORDER_TIMESTAMP::date AS Order_Date ,afi.ORDER_TIMESTAMP ,afi.QUANTITY ,ifnull(TOTAL_SALES,0)-ifnull(afi.tax,0)+ifnull(DISCOUNT_BEFORE_TAX,0) AS GROSS_SALES_BEFORE_TAX ,DISCOUNT_BEFORE_TAX AS DISCOUNT ,afi.TAX ,afi.SHIPPING_PRICE ,TOTAL_SALES AS SELLING_PRICE ,upper(coalesce(EEFI.order_status,UFI.order_status)) as OMS_order_status ,upper(coalesce(EEFI.shipping_status,UFI.shipping_status)) AS SHIPPING_STATUS ,upper(coalesce(shipmap.final_shipping_status,EEFI.shipping_status,UFI.shipping_status)) FINAL_SHIPPING_STATUS ,concat(afi.ORDER_ID,\'-\',afi.PRODUCT_ID) as SALEORDERITEMCODE ,concat(afi.ORDER_ID,\'-\',afi.PRODUCT_ID) as SALES_ORDER_ITEM_ID ,coalesce(EEFI.awb,UFI.awb) AWB ,NULL Payment_Gateway ,upper(coalesce(EEFI.payment_mode,UFI.payment_mode)) Payment_Mode ,Upper(coalesce(EEFI.Courier,UFI.courier)) AS COURIER ,coalesce(EEFI.manifest_date,UFI.dispatch_date) AS DISPATCH_DATE ,coalesce(EEFI.delivered_date,UFI.delivery_date) AS DELIVERED_DATE ,case when lower(coalesce(shipmap.final_shipping_status,ufi.shipping_status, eefi.shipping_status)) = \'delivered\' then 1 else 0 end AS DELIVERED_STATUS ,afi.IS_REFUND AS RETURN_FLAG ,case when afi.is_refund = 1 then quantity::int end returned_quantity ,case when afi.is_refund = 1 then total_sales end returned_sales ,case when afi.is_refund = 0 and lower(afi.order_status) in (\'cancelled\') then quantity::int end cancelled_quantity ,NULL as NEW_CUSTOMER_FLAG ,NULL as ACQUISITION_PRODUCT ,case when lower(coalesce(shipmap.final_shipping_status,EEFI.shipping_status,UFI.shipping_status)) in (\'delivered\',\'delivered to origin\') then datediff(day,date(afi.ORDER_TIMESTAMP),date(coalesce(ufi.shipping_last_update_date::datetime, eefi.shipping_last_update_date::datetime))) when lower(coalesce( shipmap.final_shipping_status,EEFI.shipping_status,UFI.shipping_status)) in (\'in transit\', \'shipment created\') then datediff(day,date(afi.ORDER_TIMESTAMP), getdate()) end::int as Days_in_Shipment ,NULL AS ACQUSITION_DATE ,coalesce(afi.SKU,ufi.PRODUCT_ID,eefi.SKU) as SKU_CODE ,UPPER(AFI.PRODUCT_NAME_FINAL) PRODUCT_NAME_FINAL ,UPPER(AFI.PRODUCT_CATEGORY) PRODUCT_CATEGORY ,upper(AFI.PRODUCT_SUB_CATEGORY) PRODUCT_SUB_CATEGORY ,upper(EEFI.warehouse_name) WAREHOUSE ,coalesce(AFI.pincode,EEFI.pincode) as pincode ,coalesce(EEFI.source_pincode,null) as source_pincode from RUBYSORGANICS_DB.MAPLEMONK.RUBYSORGANICS_DB_AMAZON_FACT_ITEMS AFI left join (select * from ( select * ,row_number()over(partition by reference_code, sku order by last_update_date desc) rw from RUBYSORGANICS_DB.MAPLEMONK.RUBYSORGANICS_DB_EasyEcom_FACT_ITEMS ) z where z.rw = 1 and lower(marketplace) like any (\'%amazon%\') ) EEFI on AFI.Order_id = EEFI.reference_code and AFI.sku = EEFI.sku left join (select * from (select order_id ,city ,state ,product_id ,shippingpackagecode ,SHIPPINGPACKAGESTATUS ,shipping_status ,order_status ,Courier ,Dispatch_Date ,Delivery_date ,Return_flag ,Return_quantity ,cancelled_quantity ,shipping_last_update_date ,awb ,payment_method ,MARKETPLACE_SKU ,payment_mode ,email ,row_number() over (partition by order_id, product_id order by shipping_last_update_date desc) rw from RUBYSORGANICS_DB.MAPLEMONK.RUBYSORGANICS_DB_UNICOMMERCE_FACT_ITEMS where lower(marketplace) like any (\'%amazon%\')) where rw=1 ) UFI on AFI.order_id = UFI.order_id and AFI.sku = UFI.MARKETPLACE_SKU left join ( select * from ( select upper(Shipping_status) shipping_status ,upper(mapped_status) final_shipping_status ,row_number() over (partition by lower(shipping_Status) order by 1) rw from RUBYSORGANICS_DB.MAPLEMONK.shipment_status_mapping ) where rw = 1 ) ShipMap on lower(coalesce(EEFI.shipping_status,UFI.shipping_status,afi.ORDER_STATUS)) = lower(ShipMap.shipping_status) union all select Null as customer_id ,upper(SHOP_NAME) as SHOP_NAME ,upper(marketplace) AS marketplace ,upper(marketplace) AS CHANNEL ,upper(marketplace) AS SOURCE ,ORDER_ID ,reference_code ,contact_num as PHONE ,customer_name as NAME ,email as EMAIL ,shipping_last_update_date AS SHIPPING_LAST_UPDATE_DATE ,SKU ,PRODUCT_ID ,upper(PRODUCTNAME) AS PRODUCT_NAME ,CURRENCY ,upper(CITY) City ,upper(STATE) AS State ,upper(ORDER_STATUS) as Order_Status ,ORDER_DATE::date AS Order_Date ,ORDER_DATE ,SUBORDER_QUANTITY AS QUANTITY ,ifnull(SELLING_PRICE,0)-ifnull(tax,0)+ifnull(DISCOUNT,0) AS GROSS_SALES_BEFORE_TAX ,DISCOUNT AS DISCOUNT ,TAX ,SHIPPING_PRICE ,SELLING_PRICE AS SELLING_PRICE ,upper(ORDER_STATUS) as OMS_Order_Status ,upper(b.Shipping_status) AS SHIPPING_STATUS ,upper(coalesce(shipmap.final_shipping_status,b.shipping_status)) FINAL_SHIPPING_STATUS ,Marketplace_LineItem_ID as SALEORDERITEMCODE ,suborder_id as SALES_ORDER_ITEM_ID ,AWB ,NULL Payment_Gateway ,payment_mode Payment_Mode ,UPPER(COURIER) COURIER ,MANIFEST_DATE as DISPATCH_DATE ,DELIVERED_DATE ,case when lower(coalesce(ShipMap.shipping_status,b.shipping_status)) = \'delivered\' then 1 else 0 end AS DELIVERED_STATUS ,IS_REFUND AS RETURN_FLAG ,case when is_refund = 1 then suborder_quantity::int end returned_quantity ,case when RETURN_FLAG = 1 and lower(order_status) not in (\'cancelled\') then ifnull(is_refund,0) end returned_sales ,case when is_refund = 0 and lower(order_status) in (\'cancelled\') then suborder_quantity::int end cancelled_quantity ,new_customer_flag::varchar as NEW_CUSTOMER_FLAG ,NULL as ACQUISITION_PRODUCT ,Days_in_shipment AS DAYS_IN_SHIPMENT ,NULL AS ACQUSITION_DATE ,SKU as SKU_CODE ,upper(mapped_product_name) as PRODUCT_NAME_FINAL ,upper(mapped_category) as PRODUCT_CATEGORY ,upper(mapped_sub_category) as PRODUCT_SUB_CATEGORY ,upper(WAREHOUSE_NAME) WAREHOUSE ,pincode ,coalesce(b.source_pincode,null) as source_pincode from RUBYSORGANICS_DB.MAPLEMONK.RUBYSORGANICS_DB_EasyEcom_FACT_ITEMS b left join ( select * from ( select upper(Shipping_status) shipping_status ,upper(mapped_status) final_shipping_status ,row_number() over (partition by lower(shipping_Status) order by 1) rw from RUBYSORGANICS_DB.MAPLEMONK.shipment_status_mapping ) where rw = 1 ) ShipMap on lower(coalesce(b.shipping_status,b.order_status)) = lower(ShipMap.shipping_status) where lower(marketplace) not like (\'%amazon%\') and lower(marketplace) not like (\'%shopify%\') union all select Null as customer_id ,upper(marketplace) shop_name ,upper(marketplace) marektplace ,upper(marketplace) AS CHANNEL ,upper(marketplace) AS SOURCE ,ORDER_ID ,reference_code ,phone as PHONE ,name as NAME ,email as EMAIL ,shipping_last_update_date AS SHIPPING_LAST_UPDATE_DATE ,SKU ,b.PRODUCT_ID ,PRODUCT_NAME AS PRODUCT_NAME ,CURRENCY ,upper(CITY) as city ,upper(STATE) AS State ,upper(ORDER_STATUS) order_status ,ORDER_DATE::date AS Order_Date ,ORDER_DATE ,SUBORDER_QUANTITY AS QUANTITY ,ifnull(SELLING_PRICE,0) - ifnull(tax,0) gross_sales_before_tax ,DISCOUNT AS DISCOUNT ,TAX ,SHIPPING_PRICE ,SELLING_PRICE AS SELLING_PRICE ,upper(ORDER_STATUS) as OMS_ORDER_STATUS ,upper(b.shipping_status) AS SHIPPING_STATUS ,upper(coalesce(shipmap.final_shipping_status,b.shipping_status)) FINAL_SHIPPING_STATUS ,saleOrderItemCode as SALEORDERITEMCODE ,SALES_ORDER_ITEM_ID as SALES_ORDER_ITEM_ID ,AWB ,null as payment_gateway ,payment_mode ,COURIER ,DISPATCH_DATE AS DISPATCH_DATE ,delivery_date as delivered_date ,case when upper(FINAL_SHIPPING_STATUS) in (\'DELIVERED\') then 1 end AS DELIVERED_STATUS ,return_flag AS RETURN_FLAG ,case when return_flag = 1 then suborder_quantity::int end returned_quantity ,case when return_flag = 1 then selling_price::float end returned_sales ,case when return_flag = 0 and lower(order_status) in (\'cancelled\') then suborder_quantity::int end cancelled_quantity ,NULL as NEW_CUSTOMER_FLAG ,NULL as ACQUISITION_PRODUCT ,case when order_status=\'COMPLETE\' then delivery_date::date-order_date::date else current_date - order_date::Date end as days_in_shipment ,NULL AS ACQUSITION_DATE ,sku ,upper(b.mapped_product_name) PRODUCT_NAME_FINAL ,upper(b.mapped_category) PRODUCT_CATEGORY ,upper(b.mapped_sub_category) PRODUCT_SUB_CATEGORY ,upper(warehouse_name) warehouse ,shipping_pincode AS pincode ,null as source_pincode from RUBYSORGANICS_DB.MAPLEMONK.RUBYSORGANICS_DB_unicommerce_fact_items b left join ( select * from ( select upper(Shipping_status) shipping_status ,upper(mapped_status) final_shipping_status ,row_number() over (partition by lower(shipping_Status) order by 1) rw from RUBYSORGANICS_DB.MAPLEMONK.shipment_status_mapping ) where rw = 1 ) ShipMap on lower(coalesce(b.shipping_status,b.order_status)) = lower(ShipMap.shipping_status) where not(lower(b.marketplace) like any (\'%shopify%\',\'%amazon%\',\'%amz%\')) UNION ALL SELECT NULL::VARCHAR AS customer_id, shop_name, marketplace, CHANNEL, SOURCE, Order_id AS ORDER_ID, Order_id AS reference_code, NULL::VARCHAR AS PHONE, NULL::VARCHAR AS NAME, NULL::VARCHAR AS EMAIL, CAST(shipped_date AS TIMESTAMP) AS SHIPPING_LAST_UPDATE_DATE, SKU AS SKU, CAST(style_id AS VARCHAR) AS PRODUCT_ID, PRODUCT_NAME AS PRODUCT_NAME, NULL::VARCHAR AS CURRENCY, UPPER(CITY) AS city, UPPER(STATE) AS State, UPPER(ORDER_STATUS) AS order_status, CAST(created_date AS DATE) AS Order_Date, CAST(created_date AS TIMESTAMP) AS ORDER_TIME, QUANTITY, IFNULL(SELLING_PRICE, 0) - IFNULL(tax_recovery, 0) AS gross_sales_before_tax, DISCOUNT AS DISCOUNT, tax_recovery AS TAX, shipping_charge AS SHIPPING_PRICE, SELLING_PRICE AS SELLING_PRICE, UPPER(ORDER_STATUS) AS OMS_ORDER_STATUS, UPPER(order_status) AS SHIPPING_STATUS, UPPER(order_status) AS FINAL_SHIPPING_STATUS, NULL::VARCHAR AS SALEORDERITEMCODE, NULL::VARCHAR AS SALES_ORDER_ITEM_ID, NULL::VARCHAR AS AWB, NULL::VARCHAR AS payment_gateway, NULL::VARCHAR AS payment_mode, courier_code AS COURIER, TO_DATE(TRY_TO_TIMESTAMP(shipped_date::VARCHAR)) AS DISPATCH_DATE, CAST(delivered_date AS TIMESTAMP) AS delivered_date, CASE WHEN UPPER(order_status) IN (\'DELIVERED\') THEN 1 END AS DELIVERED_STATUS, NULL::NUMBER AS RETURN_FLAG, NULL::NUMBER AS returned_quantity, NULL::NUMBER AS returned_sales, NULL::NUMBER AS cancelled_quantity, NULL::varchar AS NEW_CUSTOMER_FLAG, NULL::VARCHAR AS ACQUISITION_PRODUCT, NULL::NUMBER AS days_in_shipment, NULL::DATE AS ACQUISITION_DATE, myntra_sku_code AS sku_code, product_name_final, PRODUCT_CATEGORY, NULL::VARCHAR AS PRODUCT_SUB_CATEGORY, CAST(seller_warehouse_id AS VARCHAR) AS warehouse, zipcode AS pincode, NULL::VARCHAR AS source_pincode FROM RUBYSORGANICS_DB.Maplemonk.RUBYSORGANICS_MYNTRA_ORDERS_FACT_ITEMS m UNION ALL SELECT NULL::VARCHAR AS customer_id, UPPER(platform) AS shop_name, \'NYKAA\' AS marketplace, UPPER(platform) AS CHANNEL, UPPER(platform) AS SOURCE, NULL::VARCHAR AS ORDER_ID, NULL::VARCHAR AS reference_code, NULL::VARCHAR AS PHONE, NULL::VARCHAR AS NAME, NULL::VARCHAR AS EMAIL, NULL::TIMESTAMP AS SHIPPING_LAST_UPDATE_DATE, SKU_NAME AS SKU, CAST(sku_code AS VARCHAR) AS PRODUCT_ID, PRODUCT_NAME_FINAL AS PRODUCT_NAME, NULL::VARCHAR AS CURRENCY, NULL::VARCHAR AS city, NULL::VARCHAR AS State, \'DELIVERED\' AS order_status, CAST(order_date AS DATE) AS Order_Date_1, CAST(order_date AS TIMESTAMP) AS ORDER_TIME, QUANTITY, SELLING_PRICE AS gross_sales_before_tax, (CAST(MRP AS INT) - Selling_Price) AS DISCOUNT, NULL::NUMBER AS TAX, NULL::NUMBER AS SHIPPING_PRICE, SELLING_PRICE AS SELLING_PRICE, NULL::VARCHAR AS OMS_ORDER_STATUS, NULL::VARCHAR AS SHIPPING_STATUS, NULL::VARCHAR AS FINAL_SHIPPING_STATUS, NULL::VARCHAR AS SALEORDERITEMCODE, NULL::VARCHAR AS SALES_ORDER_ITEM_ID, NULL::VARCHAR AS AWB, NULL::VARCHAR AS payment_gateway, NULL::VARCHAR AS payment_mode, NULL::VARCHAR AS COURIER, NULL::DATE AS DISPATCH_DATE, NULL::TIMESTAMP AS delivered_date, NULL::NUMBER AS DELIVERED_STATUS, NULL::NUMBER AS RETURN_FLAG, NULL::NUMBER AS returned_quantity, NULL::NUMBER AS returned_sales, NULL::NUMBER AS cancelled_quantity, NULL::VARCHAR AS NEW_CUSTOMER_FLAG, NULL::VARCHAR AS ACQUISITION_PRODUCT, NULL::NUMBER AS days_in_shipment, NULL::DATE AS ACQUISITION_DATE, sku_code, PRODUCT_NAME_FINAL AS PRODUCT_NAME, PRODUCT_CATEGORY, SUB_CATEGORY AS PRODUCT_SUB_CATEGORY, CAST(seller_code AS VARCHAR) AS warehouse, NULL::VARCHAR AS pincode, NULL::VARCHAR AS source_pincode FROM RUBYSORGANICS_DB.Maplemonk.RUBYS_ORGANICS_NYKAA_SALES_FACT_ITEMS UNION ALL SELECT NULL::VARCHAR AS customer_id, \'BLINKIT\' AS shop_name, \'BLINKIT\' AS marketplace, \'BLINKIT\' AS CHANNEL, \'BLINKIT\' AS SOURCE, ORDER_ID, ORDER_ID AS reference_code, NULL::VARCHAR AS PHONE, NULL::VARCHAR AS NAME, NULL::VARCHAR AS EMAIL, NULL::TIMESTAMP AS SHIPPING_LAST_UPDATE_DATE, PRODUCT_ID AS SKU, PRODUCT_ID AS PRODUCT_ID, PRODUCT_NAME AS PRODUCT_NAME, NULL::VARCHAR AS CURRENCY, CITY AS CITY, NULL::VARCHAR AS STATE, \'DELIVERED\' AS ORDER_STATUS, CAST(ORDER_DATE AS DATE) AS ORDER_DATE_1, CAST(ORDER_DATE AS TIMESTAMP) AS ORDER_TIME, QUANTITY AS QUANTITY, NULL::NUMBER AS GROSS_SALES_BEFORE_TAX, NULL::NUMBER AS DISCOUNT, NULL::NUMBER AS TAX, NULL::NUMBER AS SHIPPING_PRICE, SELLING_PRICE_RS AS SELLING_PRICE, NULL::VARCHAR AS OMS_ORDER_STATUS, NULL::VARCHAR AS SHIPPING_STATUS, NULL::VARCHAR AS FINAL_SHIPPING_STATUS, NULL::VARCHAR AS SALEORDERITEMCODE, NULL::VARCHAR AS SALES_ORDER_ITEM_ID, NULL::VARCHAR AS AWB, NULL::VARCHAR AS PAYMENT_GATEWAY, NULL::VARCHAR AS PAYMENT_MODE, \'BLINKIT\' AS COURIER, ORDER_DATE AS DISPATCH_DATE, ORDER_DATE AS DELIVERED_DATE, NULL::NUMBER AS DELIVERED_STATUS, NULL::NUMBER AS RETURN_FLAG, NULL::NUMBER AS RETURNED_QUANTITY, NULL::NUMBER AS RETURNED_SALES, NULL::NUMBER AS CANCELLED_QUANTITY, NULL::VARCHAR AS NEW_CUSTOMER_FLAG, NULL::VARCHAR AS ACQUISITION_PRODUCT, NULL::NUMBER AS DAYS_IN_SHIPMENT, NULL::DATE AS ACQUISITION_DATE, NULL::VARCHAR AS SKU_CODE, NULL::VARCHAR AS PRODUCT_NAME_FINAL, CASE WHEN LOWER(VARIANT_DESCRIPTION) LIKE \'%lipstick%\' THEN \'LIPSTICK\' WHEN LOWER(VARIANT_DESCRIPTION) LIKE \'%gel%\' THEN \'GEL\' WHEN LOWER(VARIANT_DESCRIPTION) LIKE \'%contour%\' THEN \'CONTOUR STICK\' END AS PRODUCT_CATEGORY, NULL::VARCHAR AS PRODUCT_SUB_CATEGORY, NULL::VARCHAR AS WAREHOUSE, NULL::VARCHAR AS PINCODE, NULL::VARCHAR AS SOURCE_PINCODE FROM RUBYSORGANICS_DB.MAPLEMONK.RUBYSORGANICS_BLINKIT_FACT_ITEMS ; create or replace table RUBYSORGANICS_DB.MAPLEMONK.Final_customerID as with raw_pii_data as ( select distinct nullif(nullif(lower(trim(right(regexp_replace(phone, \'[^a-zA-Z0-9]+\'), 10))), \'\'), \'null\') as phone, nullif(nullif(lower(trim(email)), \'\'), \'null\') as email from RUBYSORGANICS_DB.MAPLEMONK.RUBYSORGANICS_DB_sales_consolidated_intermediate where nullif(nullif(lower(trim(right(regexp_replace(phone, \'[^a-zA-Z0-9]+\'), 10))), \'\'), \'null\') is not null or nullif(nullif(lower(trim(email)), \'\'), \'null\') is not null ), base_data as ( select phone, email, row_number() over (order by phone, email) as row_id from raw_pii_data ), email_group_1 as ( select phone, email, row_id, min(row_id) over (partition by coalesce(email, to_varchar(row_id))) as id1 from base_data ), phone_group_1 as ( select phone, email, row_id, min(id1) over (partition by coalesce(phone, to_varchar(row_id))) as id2 from email_group_1 ), email_group_2 as ( select phone, email, row_id, min(id2) over (partition by coalesce(email, to_varchar(row_id))) as id3 from phone_group_1 ), final_group as ( select phone, email, min(id3) over (partition by coalesce(phone, to_varchar(row_id))) as final_group_id from email_group_2 ) select phone as contact_num, email, 19700000000 + dense_rank() over (order by final_group_id) as maple_monk_id from final_group; create or replace table RUBYSORGANICS_DB.MAPLEMONK.RUBYSORGANICS_DB_sales_consolidated as select coalesce(m.maple_monk_id_phone, d.maple_monk_id) as customer_id_final, min(order_date) over(partition by customer_id_final) as acquisition_date, min(case when lower(order_status) not in (\'cancelled\') then order_date end) over(partition by customer_id_final) as first_complete_order_date, m.* from ( select c.maple_monk_id as maple_monk_id_phone, o.* from RUBYSORGANICS_DB.MAPLEMONK.RUBYSORGANICS_DB_sales_consolidated_intermediate o left join ( select * from ( select contact_num as phone, maple_monk_id, row_number() over (partition by contact_num order by maple_monk_id asc) as magic from RUBYSORGANICS_DB.MAPLEMONK.Final_customerID where contact_num is not null ) where magic = 1 ) c on c.phone = nullif(nullif(lower(trim(right(regexp_replace(o.phone, \'[^a-zA-Z0-9]+\'),10))), \'\'), \'null\') ) m left join ( select distinct maple_monk_id, email from RUBYSORGANICS_DB.MAPLEMONK.Final_customerID where contact_num is null ) d on d.email = nullif(nullif(lower(trim(m.email)), \'\'), \'null\'); ALTER TABLE RUBYSORGANICS_DB.MAPLEMONK.RUBYSORGANICS_DB_sales_consolidated drop COLUMN new_customer_flag ; ALTER TABLE RUBYSORGANICS_DB.MAPLEMONK.RUBYSORGANICS_DB_sales_consolidated ADD COLUMN new_customer_flag varchar(50); ALTER TABLE RUBYSORGANICS_DB.MAPLEMONK.RUBYSORGANICS_DB_sales_consolidated ADD COLUMN new_customer_flag_month varchar(50); ALTER TABLE RUBYSORGANICS_DB.MAPLEMONK.RUBYSORGANICS_DB_sales_consolidated drop COLUMN acquisition_product ; ALTER TABLE RUBYSORGANICS_DB.MAPLEMONK.RUBYSORGANICS_DB_sales_consolidated ADD COLUMN acquisition_product varchar(16777216); ALTER TABLE RUBYSORGANICS_DB.MAPLEMONK.RUBYSORGANICS_DB_sales_consolidated ADD COLUMN acquisition_channel varchar(16777216); ALTER TABLE RUBYSORGANICS_DB.MAPLEMONK.RUBYSORGANICS_DB_sales_consolidated ADD COLUMN acquisition_marketplace varchar(16777216); UPDATE RUBYSORGANICS_DB.MAPLEMONK.RUBYSORGANICS_DB_sales_consolidated AS A SET A.new_customer_flag = B.flag FROM ( SELECT DISTINCT order_id, customer_id_final, Order_Date, CASE WHEN Order_Date = first_complete_order_date then \'New\' WHEN Order_Date < first_complete_order_date or first_complete_order_date is null THEN \'Yet to make completed order\' WHEN Order_Date > first_complete_order_date then \'Repeat\' END AS Flag FROM RUBYSORGANICS_DB.MAPLEMONK.RUBYSORGANICS_DB_sales_consolidated)AS B WHERE A.order_id = B.order_id AND A.customer_id_final = B.customer_id_final; UPDATE RUBYSORGANICS_DB.MAPLEMONK.RUBYSORGANICS_DB_sales_consolidated SET new_customer_flag = CASE WHEN new_customer_flag IS NULL and (case when lower(order_status) is null then 1=1 else lower(order_status) not in (\'cancelled\') end) THEN \'New\' WHEN new_customer_flag IS NULL and (case when lower(order_status) is null then 1=1 else lower(order_status) in (\'cancelled\') end) THEN \'Yet to make completed order\' ELSE new_customer_flag END; UPDATE RUBYSORGANICS_DB.MAPLEMONK.RUBYSORGANICS_DB_sales_consolidated AS A SET A.new_customer_flag_month = B.flag FROM ( SELECT DISTINCT order_id, customer_id_final, Order_Date, CASE WHEN Last_day(order_date, \'month\') = Last_day(first_complete_order_date, \'month\') THEN \'New\' WHEN Last_day(order_date, \'month\') < Last_day(first_complete_order_date, \'month\') or acquisition_date is null THEN \'Yet to make completed order\' WHEN Last_day(order_date, \'month\') > Last_day(first_complete_order_date, \'month\') THEN \'Repeat\' END AS Flag FROM RUBYSORGANICS_DB.MAPLEMONK.RUBYSORGANICS_DB_sales_consolidated)AS B WHERE A.order_id = B.order_id AND A.customer_id_final = B.customer_id_final; UPDATE RUBYSORGANICS_DB.MAPLEMONK.RUBYSORGANICS_DB_sales_consolidated SET new_customer_flag_month = CASE WHEN new_customer_flag_month IS NULL and (case when lower(order_status) is null then 1=1 else lower(order_status) not in (\'cancelled\') end) THEN \'New\' ELSE new_customer_flag_month END; CREATE OR replace temporary TABLE RUBYSORGANICS_DB.MAPLEMONK.temp_source_1 AS SELECT DISTINCT customer_id_final, channel, marketplace FROM ( SELECT DISTINCT customer_id_final, order_date, source as channel, shop_name as marketplace, Min(case when lower(order_status) <> \'cancelled\' then order_date end) OVER (partition BY customer_id_final) firstOrderdate FROM RUBYSORGANICS_DB.MAPLEMONK.RUBYSORGANICS_DB_sales_consolidated ) res WHERE order_date=firstorderdate; UPDATE RUBYSORGANICS_DB.MAPLEMONK.RUBYSORGANICS_DB_sales_consolidated AS a SET a.acquisition_channel=b.channel FROM RUBYSORGANICS_DB.MAPLEMONK.temp_source_1 b WHERE a.customer_id_final = b.customer_id_final; UPDATE RUBYSORGANICS_DB.MAPLEMONK.RUBYSORGANICS_DB_sales_consolidated AS a SET a.acquisition_marketplace=b.marketplace FROM RUBYSORGANICS_DB.MAPLEMONK.temp_source_1 b WHERE a.customer_id_final = b.customer_id_final; CREATE OR replace temporary TABLE RUBYSORGANICS_DB.MAPLEMONK.temp_product_1 AS SELECT DISTINCT customer_id_final, product_name_final, Row_number() OVER (partition BY customer_id_final ORDER BY SELLING_PRICE DESC) rowid FROM ( SELECT DISTINCT customer_id_final, order_date, product_name_final, SELLING_PRICE , Min(case when lower(order_status) <> \'cancelled\' then order_date end) OVER (partition BY customer_id_final) firstOrderdate FROM RUBYSORGANICS_DB.MAPLEMONK.RUBYSORGANICS_DB_sales_consolidated )res WHERE order_date=firstorderdate; UPDATE RUBYSORGANICS_DB.MAPLEMONK.RUBYSORGANICS_DB_sales_consolidated AS A SET A.acquisition_product=B.product_name_final FROM ( SELECT * FROM RUBYSORGANICS_DB.MAPLEMONK.temp_product_1 WHERE rowid=1 )B WHERE A.customer_id_final = B.customer_id_final; CREATE table if not exists RUBYSORGANICS_DB.MAPLEMONK.RUBYSORGANICS_DB_easyecom_returns_intermediate (ORDER_ID NUMBER,INVOICE_ID NUMBER,SUBORDER_ID VARIANT,REFERENCE_CODE VARCHAR,CREDIT_NOTE_ID NUMBER,ORDER_DATE TIMESTAMP_NTZ,INVOICE_DATE TIMESTAMP_NTZ,RETURN_DATE TIMESTAMP_NTZ,MANIFEST_DATE TIMESTAMP_NTZ,IMPORT_DATE TIMESTAMP_NTZ,LAST_UPDATE_DATE TIMESTAMP_NTZ,COMPANY_PRODUCT_ID VARIANT,PRODUCTNAME VARCHAR,PRODUCT_ID VARIANT,SKU VARCHAR,MARKETPLACE VARCHAR,MARKETPLACE_ID NUMBER,REPLACEMENT_ORDER NUMBER,RETURN_REASON VARCHAR,RETURNED_QUANTITY FLOAT,RETURN_AMOUNT_WITHOUT_TAX FLOAT,RETURN_TAX FLOAT,RETURN_SHIPPING_CHARGE FLOAT,RETURN_MISC FLOAT,TOTAL_RETURN_AMOUNT FLOAT) ; Create or replace table RUBYSORGANICS_DB.MAPLEMONK.RUBYSORGANICS_DB_easyecom_returns_fact_items as select ifnull(FE.Source,\'NA\') Marketing_CHANNEL ,FR.* from RUBYSORGANICS_DB.MAPLEMONK.RUBYSORGANICS_DB_easyecom_returns_intermediate FR left join (select distinct replace(reference_code,\'#\',\'\') REFERENCE_CODE, Source from RUBYSORGANICS_DB.MAPLEMONK.RUBYSORGANICS_DB_sales_consolidated) FE on FR.REFERENCE_CODE = FE.REFERENCE_CODE; CREATE table if not exists RUBYSORGANICS_DB.MAPLEMONK.RUBYSORGANICS_DB_UNICOMMERCE_RETURNS_INTERMEDIATE ( MARKETPLACE VARCHAR ,SOURCE VARCHAR ,ORDER_ID VARCHAR ,REFERENCE_CODE VARCHAR ,PHONE VARCHAR ,NAME VARCHAR ,EMAIL VARCHAR ,ORDER_DATE TIMESTAMP_NTZ ,RETURN_DISPLAYCODE VARCHAR ,RETURN_STATUS VARCHAR ,INVENTORY_RECEIVED_DATE TIMESTAMP_NTZ ,RETURN_COMPLETE_DATE TIMESTAMP_NTZ ,RETURN_INVOICE_DISPLAY_CODE VARCHAR ,RETURN_COURIER VARCHAR ,RETURN_PROVIDER_SHIPPING_STATUS VARCHAR ,RETURN_TRACKING_NUMBER VARCHAR ,RETURN_TYPE VARCHAR ,SALEORDERITEMCODE VARCHAR ,ITEMSKU VARCHAR ,ITEM_NAME VARCHAR ,INVENTORY_TYPE VARCHAR ); create or replace table RUBYSORGANICS_DB.MAPLEMONK.RUBYSORGANICS_DB_unicommerce_returns_fact_items as select ifnull(FE.channel,\'NA\') Marketing_CHANNEL ,FE.quantity RETURNED_QUANTITY ,FE.selling_price as TOTAL_RETURN_AMOUNT ,FE.tax as RETURN_TAX ,FE.selling_price - FE.tax as RETURN_AMOUNT_WITHOUT_TAX ,FR.* from RUBYSORGANICS_DB.MAPLEMONK.RUBYSORGANICS_DB_UNICOMMERCE_RETURNS_INTERMEDIATE FR left join (select replace(reference_code,\'#\',\'\') REFERENCE_CODE, SALEORDERITEMCODE, channel, Source, sum(quantity) quantity, sum(selling_price) Selling_price, sum(tax) tax from RUBYSORGANICS_DB.MAPLEMONK.RUBYSORGANICS_DB_sales_consolidated group by 1,2,3,4) FE on FR.REFERENCE_CODE = FE.REFERENCE_CODE and FR.saleOrderItemCode = FE.SALEORDERITEMCODE; create or replace table RUBYSORGANICS_DB.MAPLEMONK.RUBYSORGANICS_DB_RETURNS_CONSOLIDATED as select upper(MARKETPLACE) Marketplace ,Return_Date ,upper(Marketing_CHANNEL) Marketing_channel ,sum(RETURNED_QUANTITY) TOTAL_RETURNED_QUANTITY ,sum(TOTAL_RETURN_AMOUNT) TOTAL_RETURN_AMOUNT ,sum(RETURN_TAX) TOTAL_RETURN_TAX ,sum(RETURN_AMOUNT_WITHOUT_TAX) TOTAL_RETURN_AMOUNT_EXCL_TAX from RUBYSORGANICS_DB.MAPLEMONK.RUBYSORGANICS_DB_easyecom_returns_fact_items group by 1,2,3 union all select upper(MARKETPLACE) Marketplace ,RETURN_COMPLETE_DATE RETURN_DATE ,upper(Marketing_CHANNEL) Marketing_channel ,sum(RETURNED_QUANTITY) TOTAL_RETURNED_QUANTITY ,sum(TOTAL_RETURN_AMOUNT) TOTAL_RETURN_AMOUNT ,sum(RETURN_TAX) TOTAL_RETURN_TAX ,sum(RETURN_AMOUNT_WITHOUT_TAX) TOTAL_RETURN_AMOUNT_EXCL_TAX from RUBYSORGANICS_DB.MAPLEMONK.RUBYSORGANICS_DB_UNICOMMERCE_RETURNS_FACT_ITEMS group by 1,2,3;",
                    "transaction": true
                }
            ) }}
